module palindrome_sequence_counter(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] N,\n    input wire [7:0] K,\n    output reg [31:0] result,\n    output reg done\n);\n\n// State definitions\nlocalparam [7:0] S_IDLE                      = 8'd0;\nlocalparam [7:0] S_FIND_DIV_START           = 8'd1;\nlocalparam [7:0] S_FIND_DIV_CHECK           = 8'd2;\nlocalparam [7:0] S_FIND_DIV_STORE           = 8'd3;\nlocalparam [7:0] S_FIND_DIV_NEXT            = 8'd4;\nlocalparam [7:0] S_PREPARE                  = 8'd5;\nlocalparam [7:0] S_COMPUTE_BASE_START       = 8'd6;\nlocalparam [7:0] S_COMPUTE_BASE_LOOP        = 8'd7;\nlocalparam [7:0] S_INCLUSION_EXCLUSION_START= 8'd8;\nlocalparam [7:0] S_INCLUSION_EXCLUSION_LOOP = 8'd9;\nlocalparam [7:0] S_INCLUSION_EXCLUSION_SUB  = 8'd10;\nlocalparam [7:0] S_CONTRIBUTION             = 8'd11;\nlocalparam [7:0] S_NEXT_DIVISOR             = 8'd12;\nlocalparam [7:0] S_DONE                     = 8'd13;\n\n// Constants\nlocalparam [31:0] MOD = 32'd1000000007;\n\n// Internal registers\nreg [7:0] state;\nreg [7:0] divisors [0:31];\nreg [31:0] v_values [0:31];\nreg [7:0] divisor_count;\nreg [7:0] i_counter;\nreg [7:0] current_idx;\nreg [7:0] d;\nreg [31:0] base;\nreg [7:0] exp;\nreg [31:0] temp_v;\nreg [7:0] j_counter;\nreg [31:0] contrib;\nreg [31:0] total_sum;\nreg [7:0] k;  // For mod8 function\n\n// Helper functions\nfunction [7:0] mod8;\n    input [7:0] a;\n    input [7:0] b;\n    reg [7:0] r;\n    integer k;\nbegin\n    r = a;\n    mod8 = a % b;  // Simpler implementation for synthesis\nend\nendfunction\n\nfunction [31:0] mul_mod;\n    input [31:0] a;\n    input [31:0] b;\nbegin\n    mul_mod = (a * b) % MOD;\nend\nendfunction\n\nfunction [31:0] add_mod;\n    input [31:0] a;\n    input [31:0] b;\nbegin\n    add_mod = (a + b) % MOD;\nend\nendfunction\n\nfunction [31:0] sub_mod;\n    input [31:0] a;\n    input [31:0] b;\nbegin\n    sub_mod = (a >= b) ? (a - b) : (a + MOD - b);\nend\nendfunction\n\nfunction [31:0] pow_mod;\n    input [7:0] base_val;\n    input [7:0] exp_val;\n    reg [31:0] res;\n    integer i;\nbegin\n    res = 32'd1;\n    for (i = 0; i < exp_val; i = i + 1) begin\n        res = (res * base_val) % MOD;\n    end\n    pow_mod = res;\nend\nendfunction\n\nfunction [7:0] ceil_half;\n    input [7:0] d_val;\nbegin\n    ceil_half = (d_val + 1) >> 1;\nend\nendfunction\n\n// Main state machine\nalways @(posedge clk or negedge rst_n) begin\n    integer i;\n    if (!rst_n) begin\n        state <= S_IDLE;\n        done <= 1'b0;\n        result <= 32'd0;\n        divisor_count <= 8'd0;\n        total_sum <= 32'd0;\n        for (i = 0; i < 32; i = i + 1) begin\n            divisors[i] <= 8'd0;\n            v_values[i] <= 32'd0;\n        end\n    end else begin\n        case (state)\n            S_IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= S_FIND_DIV_START;\n                    i_counter <= 8'd1;\n                    divisor_count <= 8'd0;\n                    total_sum <= 32'd0;\n                end\n            end\n\n            S_FIND_DIV_START: begin\n                state <= S_FIND_DIV_CHECK;\n            end\n\n            S_FIND_DIV_CHECK: begin\n                if (i_counter > N) begin\n                    state <= S_PREPARE;\n                    current_idx <= 8'd0;\n                end else begin\n                    if (mod8(N, i_counter) == 8'd0) begin\n                        state <= S_FIND_DIV_STORE;\n                    end else begin\n                        state <= S_FIND_DIV_NEXT;\n                    end\n                end\n            end\n\n            S_FIND_DIV_STORE: begin\n                divisors[divisor_count] <= i_counter;\n                divisor_count <= divisor_count + 8'd1;\n                state <= S_FIND_DIV_NEXT;\n            end\n\n            S_FIND_DIV_NEXT: begin\n                i_counter <= i_counter + 8'd1;\n                state <= S_FIND_DIV_CHECK;\n            end\n\n            S_PREPARE: begin\n                if (current_idx >= divisor_count) begin\n                    state <= S_DONE;\n                end else begin\n                    d <= divisors[current_idx];\n                    exp <= ceil_half(divisors[current_idx]);\n                    state <= S_COMPUTE_BASE_START;\n                end\n            end\n\n            S_COMPUTE_BASE_START: begin\n                base <= pow_mod(K, exp);\n                state <= S_COMPUTE_BASE_LOOP;\n            end\n\n            S_COMPUTE_BASE_LOOP: begin\n                temp_v <= base;\n                j_counter <= 8'd0;\n                state <= S_INCLUSION_EXCLUSION_START;\n            end\n\n            S_INCLUSION_EXCLUSION_START: begin\n                if (j_counter >= current_idx) begin\n                    state <= S_CONTRIBUTION;\n                end else begin\n                    if (mod8(d, divisors[j_counter]) == 8'd0) begin\n                        temp_v <= sub_mod(temp_v, v_values[j_counter]);\n                    end\n                    j_counter <= j_counter + 8'd1;\n                end\n            end\n\n            S_CONTRIBUTION: begin\n                v_values[current_idx] <= temp_v;\n                if (d[0]) begin\n                    contrib <= mul_mod(temp_v, {24'd0, d});\n                end else begin\n                    contrib <= mul_mod(temp_v, {24'd0, d[7:1]});\n                end\n                state <= S_NEXT_DIVISOR;\n            end\n\n            S_NEXT_DIVISOR: begin\n                total_sum <= add_mod(total_sum, contrib);\n                current_idx <= current_idx + 8'd1;\n                state <= S_PREPARE;\n            end\n\n            S_DONE: begin\n                result <= total_sum;\n                done <= 1'b1;\n                state <= S_IDLE;\n            end\n\n            default: state <= S_IDLE;\n        endcase\n    end\nend\n\nendmodule